import { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useAccess } from "../../auth/AuthContext";

/**
 * Redirects to "/zugriffsfehler" if user has no access to given levelKey.
 * Checks localStorage (Gast) or Account progress (Schüler)
 * @param {string} levelKey e.g. "level1Passed", "level2Passed"
 */
export default function useLevelGuard(levelKey) {
  const navigate = useNavigate();
  const hasAccess = useAccess();

  useEffect(() => {
    if (!hasAccess(levelKey)) {
      navigate("/zugriffsfehler");
    }
  }, [hasAccess, levelKey, navigate]);
}
